IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'AppointmentId', N'CalledAt', N'CheckInTime', N'CreatedAt', N'IsDeleted', N'Priority', N'QueueNumber', N'Status', N'UpdatedAt') AND [object_id] = OBJECT_ID(N'[QueueTickets]'))
