IF EXISTS (SELECT * FROM [sys].[identity_columns] WHERE [name] IN (N'Id', N'CreatedAt', N'Diagnosis', N'ExamEndTime', N'ExamStartTime', N'IsDeleted', N'Notes', N'Prescription', N'QueueTicketId', N'Status', N'Symptoms', N'UpdatedAt') AND [object_id] = OBJECT_ID(N'[MedicalReports]'))
    SET IDENTITY_INSERT [MedicalReports] ON;
